const N = 200000;
const STRIDE = 200; // bytes per AoS struct
// AoS: hot field (8 bytes) buried inside a 200-byte struct
const aos = new Float64Array(N * (STRIDE / 8));
for (let i = 0; i < N; i++) aos[i * (STRIDE / 8)] = i % 7;
// SoA: hot fields packed into their own contiguous array
const soa = new Float64Array(N);
for (let i = 0; i < N; i++) soa[i] = i % 7;

function sumAoS() { let s = 0; for (let i = 0; i < N; i++) s += aos[i * (STRIDE / 8)]; return s; }
function sumSoA() { let s = 0; for (let i = 0; i < N; i++) s += soa[i]; return s; }

// warm up
for (let r = 0; r < 50; r++) { sumAoS(); sumSoA(); }
let tA = performance.now(); for (let r = 0; r < 200; r++) sumAoS(); tA = performance.now() - tA;
let tS = performance.now(); for (let r = 0; r < 200; r++) sumSoA(); tS = performance.now() - tS;
console.log('AoS ms=' + tA.toFixed(1) + ' SoA ms=' + tS.toFixed(1) + ' speedup=' + (tA / tS).toFixed(2) + 'x');
